"use client";

import * as React from "react";
import {
  Box,
  Container,
  Stack,
  Link,
  Typography,
  IconButton,
  Button,
} from "@mui/joy";
import { useState, useEffect } from "react";
import Image from "next/image";
import NextLink from "next/link";
import { AboutPage, CaseStudyPage, ContactPage, ServicesPage, WorkPage } from "./content";
import { defaultImages } from "./data";
export type WebsitePage = "home" | "services" | "work" | "about" | "contact" | "case-study";
import { motion, useReducedMotion } from "framer-motion";
import Footer from "./footer";
import styles from "./resume.module.css";
import "./fonts.css";
import {
  TbArrowUp,
  TbMail,
} from "react-icons/tb";

export default function AlexandriaResume({ portraitUrl = "https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=1000&q=85", imageUrls = defaultImages, registryHref = "https://github.com/mesbahismail/Alexandria", page = "home", projectSlug }: { portraitUrl?: string; imageUrls?: string[]; registryHref?: string; page?: WebsitePage; projectSlug?: string }) {
  const reduceMotion = useReducedMotion();
  const [isScrolled, setIsScrolled] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });


  const handleMouseMove = (e: React.MouseEvent) => {
    if (reduceMotion) return;
    const { clientX, clientY } = e;
    setMousePos({
      x: (clientX / window.innerWidth - 0.5) * 10,
      y: (clientY / window.innerHeight - 0.5) * 10,
    });
  };

  const layers = [
    { id: 3, bg: "transparent", border: "solid 4px #E1B77B", content: null },
    {
      id: 2,
      bg: "transparent",
      content: (
        <Image
          src={portraitUrl}
          alt="Alexandria Klaus portrait"
          fill
          priority
          unoptimized
          quality={90}
          style={{ objectFit: "cover", borderRadius: "var(--joy-radius-sm)" }}
          sizes="520px"
        />
      ),
    },
    { id: 1, bg: "#444444", content: null },
  ];

  // Scroll handlers
  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: reduceMotion ? "instant" : "smooth" });
  };

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 10);
      setShowScrollTop(window.scrollY > 300);
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <Box id="top" className={`${styles.site} ${page === "home" ? styles.homePage : ""}`} sx={{ bgcolor: "#151516", minHeight: "100vh" }}>
      <a className={styles.skipLink} href="#main-content">Skip to content</a>
      {/* Cover light */}
      <Box
        sx={{
          position: "absolute",
          width: "1000px",
          height: "600px",
          borderRadius: "50%",
          backgroundColor: "#242426",
          filter: "blur(500px)",
          zIndex: 0,
          top: "-200px",
          left: "50%",
          transform: "translateX(-50%)",
        }}
      />

      <Container
        disableGutters
        sx={{ maxWidth: "1384px", position: "relative", px: { xs: 2, md: 0 } }}
      >
        {/* Header */}
        <Stack component="header" className={styles.header}
          direction="row"
          justifyContent="space-between"
          alignItems="center"
          spacing={2}
          sx={{
            height: "72px",
            position: "sticky",
            top: 0,
            backgroundColor: isScrolled
              ? "rgba(21, 21, 22, 0.70)"
              : "transparent",
            backdropFilter: isScrolled ? "blur(10px)" : "none",
            transition: "background-color 0.3s ease, backdrop-filter 0.3s ease",
            zIndex: 1000,
            width: "100%",
            margin: "0 auto",
            "&:before": {
              content: '""',
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: isScrolled
                ? "rgba(21, 21, 22, 0.35)"
                : "transparent",
              backdropFilter: isScrolled ? "blur(10px)" : "none",
              zIndex: -1,
            },
          }}
        >
          <Typography component={NextLink} href="/" level="h3" sx={{ color: "#ffffff", letterSpacing: "0.08em", textDecoration: "none" }}>
            ALEXANDRIA
          </Typography>

          <Stack
            direction="row"
            spacing={6}
            sx={{ alignItems: "center", pl: 4, pr: 4 }}
            className={styles.navigation}
            component="nav"
            aria-label="Main navigation"
          >
            {[
              { label: "HOME", href: "/", key: "home" },
              { label: "SERVICES", href: "/services", key: "services" },
              { label: "WORK", href: "/work", key: "work" },
              { label: "ABOUT", href: "/about", key: "about" },
            ].map((item) => <Link
              key={item.href}
              component={NextLink}
              href={item.href}
              aria-current={page === item.key || (page === "case-study" && item.key === "work") ? "page" : undefined}
              level="body-sm"
              underline="none"
              sx={{ color: "#8696A1", fontWeight: 500, "&:hover": { color: "#fff" } }}
            >{item.label}</Link>)}
          </Stack>


          <Button
            component={NextLink}
            href="/contact"
            aria-current={page === "contact" ? "page" : undefined}
            startDecorator={<TbMail size={20} />}
            sx={{
              backgroundColor: "transparent",
              border: "2px solid #E1B77B",
              color: "#fff",
              borderRadius: "0px",
              minHeight: "48px",
              padding: "0px 16px",
              width: "fit-content",
              minWidth: "unset",
              transition: "background-color 0.3s ease, transform 0.2s ease",
              "&:hover": {
                backgroundColor: "#E1B77B",
                color: "#111",
                border: "2px solid #E1B77B",
              },
              "&&": { fontWeight: 600 },
            }}
          >
            GET IN TOUCH
          </Button>
        </Stack>

        <main id="main-content">
        {page === "home" && (
        <Stack id="about" className={styles.hero}
          direction="row"
          spacing={8}
          sx={{ alignItems: "center", pt: 2, pr: 4 }}
        >
          <Stack
            direction="column"
            width={634}
            spacing={2}
            sx={{ mb: 2, mt: 4 }}
            className={styles.heroCopy}
          >
            <Stack direction="column" spacing={0.5} sx={{ pb: 3 }}>
              <Typography className={styles.heroName} level="h1" fontWeight="400" sx={{ color: "#ffffff" }}>
                Alexandria<br /><span className={styles.headlineAccent}>Klaus</span>
              </Typography>
              <Typography level="h4" fontWeight="400" sx={{ color: "#AAAAAA" }}>
                Product Designer
              </Typography>
            </Stack>

            <Box
              sx={{ width: "48px", height: "4px", backgroundColor: "#E1B77B" }}
            />

            <Typography className={styles.heroIntro} level="body-md" sx={{ color: "#ffffff", pt: 3 }}>
              I design thoughtful digital products that bring clarity to everyday
              experiences. My approach combines research, visual craft, and
              prototyping to turn complex challenges into simple, intuitive
              interfaces that feel effortless to use.
            </Typography>
            <Stack direction="row" spacing={2} sx={{ pt: 4 }}>
              <Button
                component={NextLink}
                href="/contact"
                startDecorator={<TbMail size={20} />}
                sx={{
                  backgroundColor: "transparent",
                  border: "2px solid #E1B77B",
                  color: "#fff",
                  borderRadius: "0px",
                  minHeight: "48px",
                  padding: "0px 16px",
                  width: "fit-content",
                  minWidth: "unset",
                  transition: "background-color 0.3s ease, transform 0.2s ease",
                  "&:hover": {
                    backgroundColor: "#E1B77B",
                    color: "#111",
                    border: "2px solid #E1B77B",
                  },
                  "&&": { fontWeight: 600 },
                }}
              >
                GET IN TOUCH
              </Button>

            </Stack>
          </Stack>

          <Box
            className={styles.portrait}
            sx={{ position: "relative", width: "600px", height: "600px" }}
            onMouseMove={handleMouseMove}
          >
            {layers.map((layer, index) => (
              <motion.div
                key={layer.id}
                style={{
                  position: "absolute",
                  top: `${index * 20}px`,
                  left: `${index * 20}px`,
                  width: "520px",
                  height: "520px",
                  border: index === 0 ? "2px solid #E1B77B" : "none",
                  borderRadius: "0px",
                  overflow: "hidden",
                  backgroundColor: layer.bg,
                  zIndex: layer.id,
                }}
                animate={{
                  x: reduceMotion ? 0 : mousePos.x * (layers.length - index) * 2,
                  y: reduceMotion ? 0 : mousePos.y * (layers.length - index) * 2,
                }}
                transition={{ ease: "easeOut", duration: 0.3 }}
              >
                {layer.content}
              </motion.div>
            ))}
          </Box>
        </Stack>

        )}
        {page === "services" && <ServicesPage imageUrls={imageUrls} />}
        {page === "work" && <WorkPage imageUrls={imageUrls} />}
        {page === "about" && <AboutPage portraitUrl={portraitUrl} />}
        {page === "contact" && <ContactPage />}
        {page === "case-study" && projectSlug && <CaseStudyPage slug={projectSlug} imageUrls={imageUrls} />}
        </main>

        {/* Scroll to Top Button */}
        <Box
          sx={{
            position: "fixed",
            bottom: 32,
            right: 32,
            opacity: showScrollTop ? 1 : 0,
            visibility: showScrollTop ? "visible" : "hidden",
            transition: "opacity 0.3s ease, visibility 0.3s ease",
            zIndex: 1000,
          }}
        >
          <IconButton
            aria-label="Back to top"
            variant="solid"
            color="primary"
            onClick={scrollToTop}
            sx={{
              borderRadius: "50%",
              boxShadow: "md",
              "&:hover": {
                transform: "translateY(-2px)",
                bgcolor: "primary.600",
              },
            }}
          >
            <TbArrowUp size={24} />
          </IconButton>
        </Box>
        <Footer registryHref={registryHref} compact={page === "home" || page === "contact"} />
      </Container>
    </Box>
  );
}

"use client";

import { Box, Button, Divider, Link, Stack, Typography } from "@mui/joy";
import { TbArrowUp, TbMail } from "react-icons/tb";
import NextLink from "next/link";
import styles from "./resume.module.css";

export default function Footer({ registryHref = "https://github.com/mesbahismail/Alexandria", compact = false }: { registryHref?: string; compact?: boolean }) {
  return <Box component="footer" id="contact" className={styles.footer} sx={{ pt: compact ? 0 : 6, pb: 3 }}>
    {!compact && <>
    <Divider sx={{ bgcolor: "#333333", mb: 5 }} />
    <Stack direction={{ xs: "column", sm: "row" }} justifyContent="space-between" alignItems={{ xs: "flex-start", sm: "center" }} gap={3} sx={{ pb: 5 }}>
      <Stack gap={1.5}>
        <Typography level="h3" fontWeight={400} sx={{ color: "#ffffff" }}>Let’s work <span className={styles.headlineAccent}>together.</span></Typography>
        <Box sx={{ width: "48px", height: "4px", bgcolor: "#E1B77B" }} />
        <Typography sx={{ color: "#aaa", maxWidth: 480 }}>Have a project or an opportunity in mind? Let’s start a conversation.</Typography>
      </Stack>
      <Button component={NextLink} href="/contact" startDecorator={<TbMail size={20} />} sx={{ backgroundColor: "transparent", border: "2px solid #E1B77B", color: "#fff", borderRadius: 0, minHeight: 48, px: 2, "&:hover": { bgcolor: "#E1B77B", color: "#111" } }}>GET IN TOUCH</Button>
    </Stack>
    </>}
    <Divider sx={{ bgcolor: "#333333" }} />
    <Stack direction={{ xs: "column", md: "row" }} justifyContent="space-between" alignItems={{ xs: "flex-start", md: "center" }} gap={2} sx={{ py: 3 }}>
      <Typography level="title-lg" sx={{ color: "#fff" }}>ALEXANDRIA</Typography>
      <Typography level="body-sm" sx={{ color: "#aaa" }}>© {new Date().getFullYear()} Alexandria Klaus. All rights reserved.</Typography>
      <Stack direction="row" gap={3}>
        <Link href={registryHref} underline="none" sx={{ color: "#aaa", fontSize: 13, "&:hover": { color: "#E1B77B" } }}>Component registry</Link>
        <Link href="#top" underline="none" endDecorator={<TbArrowUp />} sx={{ color: "#aaa", fontSize: 13, "&:hover": { color: "#E1B77B" } }}>Back to top</Link>
      </Stack>
    </Stack>
    <Typography level="body-xs" sx={{ color: "#888" }}>Designed with care by Ismail Mesbah · Photography via Unsplash</Typography>
  </Box>;
}

.site { overflow: clip; }
.site :global(a:focus-visible), .site :global(button:focus-visible) { outline: 2px solid #E1B77B; outline-offset: 4px; }
@media (max-width: 1200px) {
  .socials { display: none !important; }
  .hero { gap: 32px !important; }
  .heroCopy { flex: 1; min-width: 0; }
  .portrait { width: 470px !important; height: 500px !important; flex-shrink: 0; }
  .portrait > div { width: 420px !important; height: 420px !important; }
}
@media (max-width: 900px) {
  .header { flex-wrap: wrap; height: auto !important; min-height: 86px; padding-top: 12px; padding-bottom: 12px; }
  .navigation { order: 3; width: 100%; justify-content: space-between; padding: 12px 0 0 !important; margin-left: 0 !important; gap: 12px !important; }
  .navigation > a { margin-left: 0 !important; font-size: 11px; }
  .hero { flex-direction: column !important; padding-right: 0 !important; padding-top: 30px !important; }
  .hero > * { margin-left: 0 !important; }
  .heroCopy { width: 100% !important; }
  .portrait { width: min(560px, 100%) !important; height: auto !important; aspect-ratio: 1; margin-top: 24px !important; }
  .portrait > div { width: calc(100% - 50px) !important; height: calc(100% - 50px) !important; }
}
@media (max-width: 600px) {
  .site :global(#experience > .MuiStack-root:nth-of-type(2)) { flex-direction: column; gap: 28px; }
  .site :global(#experience > .MuiStack-root:nth-of-type(2) > *) { margin-left: 0; }
  .site :global(#experience .MuiDivider-vertical) { display: none; }
}
@media print {
  .header, .site :global(button), .site :global(#contact a), .site :global(#contact) { display: none !important; }
  .site { overflow: visible; print-color-adjust: exact; }
  .hero { gap: 20px !important; }
  .heroCopy { width: 55% !important; }
  .portrait { width: 300px !important; height: 300px !important; }
  .portrait > div { width: 250px !important; height: 250px !important; transform: none !important; }
}

/* A restrained contemporary finish over Alexandria’s original geometry. */
.site {
  --accent: #e1b77b;
  --champagne: #eed7b4;
  background-image: radial-gradient(ellipse at 80% 8%, rgba(225, 183, 123, .035), transparent 38%);
}
.header {
  border-bottom: 1px solid rgba(225, 183, 123, .12);
  min-height: 88px;
}
.navigation > a {
  position: relative;
  font-size: 11px;
  letter-spacing: .11em;
  color: #a5a5a6;
  transition: color .25s ease;
}
.navigation > a::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -9px;
  height: 1px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform .25s ease;
}
.navigation > a:hover::after, .navigation > a:focus-visible::after { transform: scaleX(1); }
.site :global(.MuiButton-root) {
  border-width: 1px;
  border-color: rgba(225, 183, 123, .8);
  border-radius: 2px;
  letter-spacing: .075em;
  font-size: 11px;
  min-height: 48px;
  padding-inline: 22px;
  transition: background-color .25s ease, color .25s ease, box-shadow .25s ease, transform .25s ease;
}
.site :global(.MuiButton-root:hover) {
  border-width: 1px;
  border-color: var(--champagne);
  background: var(--champagne);
  color: #151516;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(225, 183, 123, .10);
}
.socials :global(.MuiIconButton-root) { color: #a4a4a5; transition: color .25s, background-color .25s; }
.socials :global(.MuiIconButton-root:hover) { color: var(--accent); background: rgba(225, 183, 123, .06); }
.hero { padding-top: 44px !important; padding-bottom: 16px; }
.heroCopy .heroName {
  font-size: clamp(36px, 3.5vw, 51px);
  font-weight: 400;
  letter-spacing: -.035em;
  line-height: 1.13;
  text-wrap: balance;
}
.heroCopy .heroIntro { color: #c0bfc0; line-height: 1.9; max-width: 540px; }
.heroCopy > :first-child > :last-child { font-size: 19px; letter-spacing: .025em; margin-top: 10px; color: #b6b1a9; }
.portrait > div:nth-child(2) { box-shadow: 0 24px 65px rgba(0, 0, 0, .24); }
.portrait > div:first-child { border-width: 1px !important; border-color: rgba(225, 183, 123, .85) !important; }
.sectionHeading { padding-top: 24px !important; padding-bottom: 35px !important; }
.sectionHeading > :first-child { font-size: clamp(28px, 2.6vw, 36px); letter-spacing: .055em; line-height: 1.3; }
.sectionHeading > :nth-child(2) { font-size: 14px; color: #a8a6a4; font-weight: 400; letter-spacing: .015em; }
.sectionHeading > :last-child { height: 2px; background: linear-gradient(90deg, #b99561, #eed7b4); }
.site .projectCard {
  height: 100%;
  border-radius: 3px;
  overflow: hidden;
  background: #1a1a1c;
  box-shadow: 0 8px 28px rgba(0, 0, 0, .10);
  transition: transform .35s ease, box-shadow .35s ease;
}
.site .cardImage { isolation: isolate; }
.cardImage::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, transparent 65%, rgba(21, 21, 22, .18));
}
.cardImage img { transition: transform .65s cubic-bezier(.2, .6, .2, 1), filter .5s ease; filter: saturate(.82); }
.site .cardBody {
  flex: 1;
  border-width: 1px;
  border-color: #363436;
  border-top: 0;
  background: linear-gradient(125deg, rgba(255,255,255,.018), transparent);
  padding: 28px;
  transition: border-color .3s ease;
}
.cardBody :global(.MuiCardContent-root) { gap: 12px; }
.cardBody :global(.MuiTypography-titleLg) { font-size: 20px; font-weight: 500; letter-spacing: -.015em; }
.cardBody :global(.MuiTypography-bodyMd) { font-size: 14px; line-height: 1.85; }
.cardBody :global(.MuiTypography-h4) { font-weight: 400; letter-spacing: -.02em; }
.cardBody :global(.MuiIconButton-root) { border-width: 1px; border-color: #48413a; color: var(--accent); transition: transform .3s, border-color .3s, background-color .3s; }
.cardBody :global(.MuiIconButton-root:hover) { background: rgba(225,183,123,.06); border-color: var(--accent); transform: rotate(90deg); }
.site .footer { margin-top: 28px; background: radial-gradient(ellipse at 15% 45%, rgba(225,183,123,.035), transparent 65%); }
.footer :global(h3) { font-size: clamp(25px, 2.7vw, 36px); letter-spacing: .035em; }
.footer :global(a) { transition: color .25s ease; }
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .projectCard:hover { transform: translateY(-5px); box-shadow: 0 20px 45px rgba(0,0,0,.22); }
  .projectCard:hover .cardImage img { transform: scale(1.035); filter: saturate(1); }
  .projectCard:hover .cardBody { border-color: rgba(225,183,123,.45); }
}
@media (max-width: 600px) {
  .heroCopy .heroName { font-size: clamp(31px, 8.5vw, 43px); }
  .hero { padding-top: 34px !important; }
  .heroCopy .heroIntro { font-size: 15px; }
  .site .cardBody { padding: 23px; }
  .sectionHeading { padding-bottom: 28px !important; }
}
@media (prefers-reduced-motion: reduce) {
  .site *, .site *::before, .site *::after { transition: none !important; }
  .site :global(.MuiButton-root:hover) { transform: none; }
}
@media print {
  .site, .site .projectCard, .site .cardBody, .site .footer { background-image: none; box-shadow: none; }
}

/* Website pages use the same charcoal, gold, and rectangular geometry. */
.skipLink { position: fixed; left: 16px; top: -80px; z-index: 2000; padding: 12px 20px; background: #e1b77b; color: #151516; }
.skipLink:focus { top: 12px; }
.navigation > a[aria-current="page"] { color: #e1b77b; }
.navigation > a[aria-current="page"]::after { transform: scaleX(1); }
.homePage .hero { min-height: calc(100svh - 240px); }
.innerPage { padding: 58px 16px 60px; color: #f4f2ed; }
.innerPage h1, .innerPage h2, .innerPage h3, .innerPage p { margin: 0; }
.innerPage h2 { font-size: clamp(26px, 2.5vw, 36px); line-height: 1.3; font-weight: 400; letter-spacing: -.025em; }
.innerPage p { color: #aaa8a6; font-size: 15px; line-height: 1.9; }
.eyebrow { color: #e1b77b; font-size: 10px; font-weight: 500; letter-spacing: .16em; text-transform: uppercase; }
.pageHeading { padding: 16px 0 50px; max-width: 800px; }
.pageHeading h1 { margin-top: 20px; font-size: clamp(34px, 3.6vw, 50px); font-weight: 400; line-height: 1.16; letter-spacing: .025em; }
.pageHeading p { margin-top: 20px; max-width: 580px; }
.goldRule { display: block; margin-top: 28px; width: 48px; height: 2px; background: linear-gradient(90deg, #b99561, #eed7b4); }
.serviceRows { border-top: 1px solid #343234; }
.serviceRow { display: grid; grid-template-columns: 1fr 1fr; gap: 65px; padding: 44px 0; border-bottom: 1px solid #343234; align-items: center; }
.servicePhoto { position: relative; height: 365px; overflow: hidden; border-radius: 2px; }
.servicePhoto img, .workPhoto img, .aboutPortrait img, .caseHero img { object-fit: cover; filter: saturate(.82); }
.serviceCopy { padding: 16px 25px 16px 0; }
.serviceCopy h2 { margin-top: 19px; }
.serviceCopy p { margin-top: 19px; max-width: 475px; }
.serviceCopy ul, .caseDeliverables ul { display: grid; grid-template-columns: 1fr 1fr; gap: 15px 20px; padding: 0; margin: 25px 0 30px; list-style: none; }
.serviceCopy li, .caseDeliverables li { display: flex; gap: 10px; align-items: center; color: #c9c5bf; font-size: 12px; line-height: 1.5; }
.serviceCopy li svg, .caseDeliverables li svg { color: #e1b77b; flex-shrink: 0; }
.inlineLink { display: inline-flex; gap: 12px; align-items: center; color: #e1b77b; font-size: 12px; text-decoration: none; transition: color .25s; }
.inlineLink:hover { color: #eed7b4; }
.inlineLink svg { font-size: 18px; }
.workGallery { display: grid; grid-template-columns: 1fr 1fr; gap: 35px; }
.site .workLink { display: flex; flex-direction: column; color: inherit; text-decoration: none; border: 1px solid #343234; }
.workPhoto { height: 320px; position: relative; overflow: hidden; }
.workPhoto img { transition: transform .6s ease; }
.workLink:hover .workPhoto img { transform: scale(1.03); }
.imageLabel { position: absolute; left: 18px; bottom: 18px; background: #151516d9; border: 1px solid #ffffff20; backdrop-filter: blur(8px); color: #eee3d3; font-size: 8px; letter-spacing: .12em; padding: 9px 12px; }
.workCaption { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 26px 28px 16px; }
